//! `kind = "ts-program"` relay, end to end on a synthetic "foreign" source:
//! a BS-like program (network_id 0x0004, CA descriptors, ECM PID, copy
//! control, a carousel stream) whose PCR and PTS wrap around 2^33 two
//! seconds in, generated by this crate, then rebroadcast as a terrestrial
//! service. Checks: `arib-analyze` validation without errors; ES bytes
//! identical PES by PES; the source's arrival→DTS distance kept per PES;
//! CA / ECM / source copy control gone; loop continuity (PTS, arrival, CC);
//! source EIT p/f copied; `at_eof = "end"`; the rate check.

mod common;

use arib_analyze::scan::{ScanOptions, scan_packets};
use arib_analyze::validate::{Severity, ValidateOptions, validate};
use arib_mux::pcrclock::PcrClock;
use arib_mux::{Config, Multiplexer, Packet};
use arib_ts::pcr::{BASE_MODULUS, PCR_MODULUS};
use common::{bench_params, synth_audio, synth_video, tmpdir};
use std::path::{Path, PathBuf};

const HZ: u64 = 27_000_000;

/// Source TS (multiplex-frame TS of `seconds`) of a BS-like program.
fn source_ts(dir: &Path, seconds: f64) -> PathBuf {
    // equal durations (78 frames at 30000/1001 = 2.6026 s, 122 AAC frames
    // = 2.6027 s), so the source's own media loop leaves no PTS gap
    std::fs::write(dir.join("v.m2v"), synth_video(6)).unwrap();
    std::fs::write(dir.join("a.adts"), synth_audio(122)).unwrap();
    let start_pcr = PCR_MODULUS - 2 * HZ; // PCR and PTS wrap ≈ 2 s in
    let text = format!(
        r#"
[network]
network_id = 0x0004
name = "BSデジタル"
area_code = 0x5A5
remote_control_key_id = 1
channels = [27]

[transport]
transport_stream_id = 0x4090

[clock]
source = "fixed"
start = "2026-10-08T11:59:50"
start_pcr = {start_pcr}

[[service]]
service_id = 0x00D3
name = "ソース"
provider = "ソース"
layer = "B"
pmt_pid = 0x0101
pcr_pid = 0x0111
program_descriptors = [ {{ tag = 0x09, hex = "0005e121" }} ]
copy_control = {{ recording_control = "copy-one-generation", in_pmt = true, in_sdt = false }}

  [[service.stream]]
  kind = "mpeg2-video"
  pid = 0x0140
  component_tag = 0x00
  source = "v.m2v"
  descriptors = [ {{ tag = 0x09, hex = "0005ffff" }} ]

  [[service.stream]]
  kind = "aac-adts"
  pid = 0x0141
  component_tag = 0x10
  source = "a.adts"

  [[service.stream]]
  kind = "declared"
  pid = 0x0150
  stream_type = 0x0D
  component_tag = 0x40

  [[service.event]]
  event_id = 0x0101
  start = "2026-10-08T11:00:00"
  duration = "01:00:00"
  name = "元の番組"
  text = "ソースの説明"
  content = [0x70]

  [[service.event]]
  event_id = 0x0102
  start = "2026-10-08T12:00:00"
  duration = "00:30:00"
  name = "次の番組"

[[raw_table]]
pid = 0x0121
layer = "B"
interval_ms = 100
sections = ["82 70 05 01 02 03 04 05"]
"#
    );
    let cfg = Config::from_toml(&text).unwrap();
    let p = bench_params();
    let mut mux = Multiplexer::new(&cfg, &p, dir).unwrap();
    let frames = (seconds / p.frame_seconds()).ceil() as usize;
    let mut out = Vec::new();
    for _ in 0..frames {
        let (full, _) = mux.next_frame_full();
        for pk in full {
            out.extend_from_slice(&pk);
        }
    }
    for (p, v) in mux.tstd_violations() {
        assert_eq!(
            v.tb_overflow + v.buffer_overflow + v.underflow,
            0,
            "source {p:#06x}"
        );
    }
    let path = dir.join("source.ts");
    std::fs::write(&path, out).unwrap();
    path
}

fn relay_config(source: &Path, extra: &str) -> Config {
    Config::from_toml(&relay_toml(source, extra)).unwrap()
}

fn toml_of(source: &Path) -> String {
    relay_toml(source, "")
}

fn relay_toml(source: &Path, extra: &str) -> String {
    format!(
        r#"
[network]
network_id = 0x7FE0
name = "ベンチ"
area_code = 0x5A5
remote_control_key_id = 9
channels = [44]

[transport]
transport_stream_id = 0x7FE0

[clock]
source = "fixed"
start = "2026-10-09T09:00:00"

[[service]]
service_id = 0x0400
name = "再送信"
provider = "ベンチ"
layer = "B"
pmt_pid = 0x01F0
pcr_pid = 0x01FF
copy_control = {{ recording_control = "copy-free", in_pmt = true, in_sdt = true }}

  [[service.stream]]
  kind = "ts-program"
  source = "{}"
  pid_map = [[0x0140, 0x0111], [0x0141, 0x0112]]
  eit_from_source = true
{extra}
"#,
        source.display()
    )
}

fn run(cfg: &Config, seconds: f64) -> (Multiplexer, Vec<Packet>) {
    let p = bench_params();
    let mut mux = Multiplexer::new(cfg, &p, Path::new(".")).unwrap();
    let frames = (seconds / p.frame_seconds()).ceil() as usize;
    let mut out = Vec::new();
    for _ in 0..frames {
        if mux.relays_finished() {
            break;
        }
        let (full, _) = mux.next_frame_full();
        out.extend(full);
    }
    (mux, out)
}

fn packets(path: &Path) -> Vec<Packet> {
    std::fs::read(path)
        .unwrap()
        .chunks(188)
        .map(|c| c.try_into().unwrap())
        .collect()
}

fn pid(p: &Packet) -> u16 {
    (u16::from(p[1] & 0x1F) << 8) | u16::from(p[2])
}

fn ts90(b: &[u8]) -> u64 {
    ((b[0] as u64 >> 1) & 7) << 30
        | (b[1] as u64) << 22
        | ((b[2] as u64) >> 1) << 15
        | (b[3] as u64) << 7
        | (b[4] as u64) >> 1
}

/// One PES of a stream with its PCR-interpolated arrival (first byte) and
/// the decoding time mapped onto the same continuous time line.
#[derive(Debug)]
struct Pes {
    es: Vec<u8>,
    arrival: u64,
    decode: Option<i64>,
    pts90: Option<u64>,
}

/// Complete PES of `es_pid`, timed by the PCR of `pcr_pid`.
fn pes_of(pkts: &[Packet], pcr_pid: u16, es_pid: u16) -> Vec<Pes> {
    let mut clock = PcrClock::new(Some(pcr_pid));
    let mut timed = Vec::new();
    for (i, p) in pkts.iter().enumerate() {
        clock.push(p, i);
        timed.extend(std::iter::from_fn(|| clock.pop()));
    }
    clock.finish();
    timed.extend(std::iter::from_fn(|| clock.pop()));
    let mut out: Vec<Pes> = Vec::new();
    let mut cur: Option<(Vec<u8>, u64, Option<arib_mux::pcrclock::Anchor>)> = None;
    let close = |c: (Vec<u8>, u64, Option<arib_mux::pcrclock::Anchor>), out: &mut Vec<Pes>| {
        let (b, t, a) = c;
        let len = u16::from_be_bytes([b[4], b[5]]) as usize;
        if len != 0 && b.len() < 6 + len {
            return; // incomplete (cut by the end of the stream)
        }
        let flags = b[7] >> 6;
        let pts = (flags & 2 != 0).then(|| ts90(&b[9..14]));
        let dts = if flags == 3 {
            Some(ts90(&b[14..19]))
        } else {
            pts
        };
        out.push(Pes {
            es: b[9 + b[8] as usize..].to_vec(),
            arrival: t,
            decode: dts.and_then(|d| a.map(|a| a.map90(d))),
            pts90: pts,
        });
    };
    for x in timed {
        let p = &pkts[x.item];
        if pid(p) != es_pid {
            continue;
        }
        let afc = (p[3] >> 4) & 3;
        if afc & 1 == 0 {
            continue;
        }
        let s = if afc & 2 != 0 { 5 + p[4] as usize } else { 4 };
        if p[1] & 0x40 != 0 {
            if let Some(c) = cur.take() {
                close(c, &mut out);
            }
            cur = Some((p[s..].to_vec(), x.t, x.anchor));
        } else if let Some(c) = cur.as_mut() {
            c.0.extend_from_slice(&p[s..]);
        }
    }
    if let Some(c) = cur.take() {
        close(c, &mut out);
    }
    out
}

fn no_validation_errors(pkts: &[Packet], what: &str) {
    let cap = scan_packets(pkts, &ScanOptions::default());
    let r = validate(&cap, &ValidateOptions::default());
    assert!(!r.has_errors(), "{what}:\n{}", r.to_text(Severity::Error));
}

#[test]
fn relays_a_foreign_program_as_a_terrestrial_service() {
    let dir = tmpdir("relay-foreign");
    let src_path = source_ts(&dir, 8.0);
    let src = packets(&src_path);
    no_validation_errors(&src, "synthetic source");
    let cfg = relay_config(&src_path, r#"  at_eof = "loop""#);
    let (mux, out) = run(&cfg, 21.0);

    // ---- report: selection, carried and dropped descriptors
    let notes = mux.notes().join("\n");
    assert!(
        notes.contains("relay 0x0140 -> 0x0111 video (stream_type 0x02"),
        "{notes}"
    );
    assert!(
        notes.contains("relay 0x0141 -> 0x0112 audio (main) (stream_type 0x0f"),
        "{notes}"
    );
    assert!(
        notes.contains("not relayed: 0x0150 data carousel stream_type 0x0d"),
        "{notes}"
    );
    assert!(
        notes.contains("dropped: [conditional_access_descriptor (0x09)]"),
        "{notes}"
    );
    assert!(
        notes.contains("source program descriptors dropped: [digital_copy_control_descriptor (0xc1), conditional_access_descriptor (0x09)]")
            || notes.contains("source program descriptors dropped: [conditional_access_descriptor (0x09), digital_copy_control_descriptor (0xc1)]"),
        "{notes}"
    );

    // ---- conformance of the rebroadcast TS
    no_validation_errors(&out, "relay output");
    let st = mux.relay_stats()[0];
    assert!(st.passes >= 2, "{st:?}");
    assert_eq!(st.late_pes, 0, "{st:?}");
    assert_eq!(
        st.cc_errors + st.pes_dropped + st.tei + st.scrambled,
        0,
        "{st:?}"
    );
    for (p, v) in mux.tstd_violations() {
        assert_eq!(
            v.tb_overflow + v.buffer_overflow + v.underflow,
            0,
            "{p:#06x} {v:?}"
        );
    }

    // ---- CA / ECM / foreign SI gone; our PSI/SI present
    let cap = scan_packets(&out, &ScanOptions::default());
    assert!(!out.iter().any(|p| pid(p) == 0x0121), "ECM PID relayed");
    assert!(
        notes.contains("dropped PID 0x0121: ECM (CA_PID of a conditional_access_descriptor, CA_system_id 0x0005)"),
        "{notes}"
    );
    assert!(
        notes.contains("dropped PID 0x0111: PCR of the program"),
        "{notes}"
    );
    assert!(
        !out.iter()
            .any(|p| matches!(pid(p), 0x0140 | 0x0141 | 0x0150))
    );
    let pmts = cap.pmts();
    let (_, pmt) = pmts.values().next().expect("PMT");
    assert_eq!(pmt.header.table_id_extension, 0x0400);
    assert_eq!(pmt.body.pcr_pid, 0x01FF);
    assert!(pmt.body.program_info.iter().all(|d| d.tag != 0x09));
    // our copy control (copy-free, B10 Table 6-39 '00'), not the source's
    let c1: Vec<_> = pmt
        .body
        .program_info
        .iter()
        .filter(|d| d.tag == 0xC1)
        .collect();
    assert_eq!(c1.len(), 1);
    assert_eq!(c1[0].data[0] >> 6, 0b00);
    let streams: Vec<(u8, u16, Vec<u8>)> = pmt
        .body
        .streams
        .iter()
        .map(|s| {
            (
                s.stream_type,
                s.elementary_pid,
                s.descriptors.iter().map(|d| d.tag).collect(),
            )
        })
        .collect();
    assert_eq!(
        streams,
        vec![
            // stream_identifier carried (typed component_tag), 0xC8 derived from the sequence header
            (0x02, 0x0111, vec![0x52, 0xC8]),
            (0x0F, 0x0112, vec![0x52]),
        ]
    );

    // ---- ES bytes identical, PES by PES; arrival→DTS kept; loops continuous
    for (spid, dpid) in [(0x0140u16, 0x0111u16), (0x0141, 0x0112)] {
        let s = pes_of(&src, 0x0111, spid);
        let d = pes_of(&out, 0x01FF, dpid);
        assert!(
            d.len() > s.len(),
            "{dpid:#06x}: {} relayed PES, source {}",
            d.len(),
            s.len()
        );
        // first relayed PES = source PES j0 (the cut-in); same bytes from there
        let j0 = s.iter().position(|x| x.es == d[0].es).unwrap();
        let shift = d[0].decode.unwrap() - s[j0].decode.unwrap();
        let mut j = j0;
        let mut passes = 1;
        let mut prev_decode = i64::MIN;
        let mut prev_arrival = 0;
        for (k, x) in d.iter().enumerate() {
            if j == s.len() {
                // seam: the next pass starts again at the cut-in
                j = j0;
                passes += 1;
            }
            assert_eq!(x.es, s[j].es, "{dpid:#06x} PES {k} ≠ source PES {j}");
            let (dd, sd) = (x.decode.unwrap(), s[j].decode.unwrap());
            // PTS/DTS: same constant shift within a pass (exact in 90 kHz)
            if passes == 1 {
                assert_eq!(dd - sd, shift, "{dpid:#06x} PES {k}");
            }
            assert!(
                dd > prev_decode,
                "{dpid:#06x} PES {k}: decode time not increasing"
            );
            assert!(x.arrival >= prev_arrival, "{dpid:#06x} PES {k}: arrival");
            // arrival → decode distance as in the source: within a few
            // slots of jitter in the first pass; after a seam the T-STD hold
            // may delay the next pass's front-loaded start (never early,
            // never past the decoding time)
            let (rd, sdist) = (dd - x.arrival as i64, sd - s[j].arrival as i64);
            let ok = if passes == 1 {
                (rd - sdist).abs() < (HZ / 200) as i64
            } else {
                rd <= sdist + (HZ / 200) as i64 && sdist - rd < (HZ / 2) as i64 && rd > 0
            };
            assert!(
                ok,
                "{dpid:#06x} PES {k} (pass {passes}): arrival→DTS {} ms vs source {} ms",
                rd as f64 / 27e3,
                sdist as f64 / 27e3
            );
            prev_decode = dd;
            prev_arrival = x.arrival;
            j += 1;
        }
        assert!(passes >= 2, "{dpid:#06x}: {passes} passes");
        // consecutive 33-bit PTS (decode order, B-pictures reordered) stay
        // within ±1 s modulo 2^33: no jump at the seams
        for x in d.windows(2) {
            let (a, b) = (x[0].pts90.unwrap(), x[1].pts90.unwrap());
            let diff = ((b + BASE_MODULUS - a) % BASE_MODULUS) as i64;
            let diff = if diff >= (BASE_MODULUS / 2) as i64 {
                diff - BASE_MODULUS as i64
            } else {
                diff
            };
            assert!(diff.abs() < 90_000, "PTS jump {a} → {b}");
        }
    }

    // ---- EIT p/f from the source, re-encoded
    let eit: Vec<String> = cap
        .latest_sections()
        .filter(|(k, _)| k.table_id == 0x4E)
        .filter_map(|(_, sec)| arib_ts::section::Long::<arib_si::tables::EitBody>::decode(sec).ok())
        .flat_map(|e| e.body.events)
        .flat_map(|e| e.descriptors)
        .filter_map(|d| match d {
            arib_si::Descriptor::ShortEvent(s) => Some(s.event_name.decode().text),
            _ => None,
        })
        .collect();
    // the source present event ends 10 s after the source's TOT (11:59:50):
    // placed 3590 s before the relay start, the following one 10 s after it;
    // by the end of the run the following event is the present one
    assert!(
        notes.contains("0x0101 \"元の番組\" 01:00:00 at -359"),
        "{notes}"
    );
    assert!(
        notes.contains("0x0102 \"次の番組\" 00:30:00 at +1"),
        "{notes}"
    );
    assert!(eit.contains(&"次の番組".to_string()), "{eit:?}");
}

#[test]
fn ends_at_eof_and_refuses_a_layer_that_is_too_small() {
    let dir = tmpdir("relay-end");
    let src_path = source_ts(&dir, 4.0);
    let cfg = relay_config(&src_path, r#"  at_eof = "end""#);
    let (mux, out) = run(&cfg, 30.0);
    assert!(mux.relays_finished());
    let st = mux.relay_stats()[0];
    assert_eq!(st.passes, 1);
    let secs = out.len() as f64 / bench_params().multiplex_frame_tsps() as f64
        * bench_params().frame_seconds();
    assert!((3.0..5.0).contains(&secs), "ended after {secs} s");
    no_validation_errors(&out, "relay output (at_eof = end)");

    // Layer B of one QPSK 1/2 segment (0.31 Mbit/s) cannot carry ≈ 3 Mbit/s.
    use isdbt_core::{
        CodeRate, GuardInterval, LayerConfig, Mode, Modulation, Params, TimeInterleave,
    };
    let l = |segments, modulation, code_rate| {
        Some(LayerConfig {
            segments,
            modulation,
            code_rate,
            time_interleave: TimeInterleave(2),
        })
    };
    let small = Params::new(
        Mode::M3,
        GuardInterval::G1_8,
        true,
        [
            l(1, Modulation::Qpsk, CodeRate::R2_3),
            l(1, Modulation::Qpsk, CodeRate::R1_2),
            l(11, Modulation::Qam64, CodeRate::R3_4),
        ],
    )
    .unwrap();
    let e = Multiplexer::new(&cfg, &small, Path::new("."))
        .err()
        .expect("refused")
        .to_string();
    assert!(e.contains("but layer B (1seg QPSK 1/2"), "{e}");
    assert!(e.contains("layouts that fit"), "{e}");
    // no 1-segment layer B carries it: a single 13-segment layer does
    assert!(e.contains("--partial false --layer-a 13,qpsk,1/2,2"), "{e}");
    // rate_check = "warn" relays anyway, with a warning
    let warn = relay_config(&src_path, "  at_eof = \"end\"\n  rate_check = \"warn\"");
    let m = Multiplexer::new(&warn, &small, Path::new(".")).unwrap();
    assert!(
        m.warnings().iter().any(|w| w.contains("layouts that fit")),
        "{:?}",
        m.warnings()
    );
}

#[test]
fn ts_program_keys_are_checked() {
    let dir = tmpdir("relay-keys");
    let src = dir.join("none.ts");
    let base = |extra: &str| {
        format!(
            r#"
[network]
network_id = 0x7FE0
name = "n"
area_code = 1
remote_control_key_id = 9
channels = [44]
[transport]
transport_stream_id = 1
[[service]]
service_id = 1
name = "s"
layer = "B"
pmt_pid = 0x01F0
pcr_pid = 0x01FF
  [[service.stream]]
{extra}
"#
        )
    };
    // relay keys on another kind
    let e = Config::from_toml(&base(
        "  kind = \"declared\"\n  pid = 0x0111\n  stream_type = 2\n  at_eof = \"end\"",
    ))
    .unwrap_err()
    .to_string();
    assert!(e.contains("apply only to kind = \"ts-program\""), "{e}");
    // a ts-program takes its PIDs from the source
    let e = Config::from_toml(&base(&format!(
        "  kind = \"ts-program\"\n  source = \"{}\"\n  pid = 0x0111",
        src.display()
    )))
    .unwrap_err()
    .to_string();
    assert!(e.contains("pid_map"), "{e}");
    let e = Config::from_toml(&base("  kind = \"ts-program\""))
        .unwrap_err()
        .to_string();
    assert!(e.contains("needs source"), "{e}");
    // a missing file is a media error at multiplexer creation
    let cfg = Config::from_toml(&base(&format!(
        "  kind = \"ts-program\"\n  source = \"{}\"",
        src.display()
    )))
    .unwrap();
    let e = Multiplexer::new(&cfg, &bench_params(), Path::new("."))
        .err()
        .unwrap()
        .to_string();
    assert!(e.contains("none.ts"), "{e}");
}

#[test]
fn relay_example_parses() {
    let cfg = Config::from_toml(include_str!("../examples/relay-ts.toml")).unwrap();
    let st = &cfg.services[0].streams[0];
    assert_eq!(st.kind, arib_mux::config::StreamKind::TsProgram);
    // program and PIDs come from the recording: no program, pid_map "auto"
    assert_eq!(st.program, None);
    assert!(st.pid_map.is_auto() && st.pids.is_none());
    assert_eq!(cfg.network.channels, vec![44]);
    assert_eq!(cfg.network.remote_control_key_id.get(), 9);
}

/// `recording_control = "source"` (the `--relay` default) keeps the source
/// program's copy restriction: the synthetic source signals
/// copy-one-generation ('10') in its PMT program loop, so the relay's 0xC1
/// carries '10' too, with copy_control_type '01' (user_defined 0b0100).
#[test]
fn source_copy_control_is_preserved() {
    let dir = tmpdir("relay-copy-source");
    let src_path = source_ts(&dir, 4.0);
    let text = toml_of(&src_path).replace(
        r#"recording_control = "copy-free""#,
        r#"recording_control = "source""#,
    );
    let cfg = Config::from_toml(&text).unwrap();
    let (mux, out) = run(&cfg, 3.0);
    let notes = mux.notes().join("\n");
    assert!(
        notes.contains(
            "source copy control: copy-one-generation ('10') from the source PMT program loop"
        ),
        "{notes}"
    );
    assert!(
        notes.contains("recording_control = \"source\" -> \"copy-one-generation\""),
        "{notes}"
    );
    let cap = scan_packets(&out, &ScanOptions::default());
    let pmts = cap.pmts();
    let (_, pmt) = pmts.values().next().expect("PMT");
    let c1: Vec<_> = pmt
        .body
        .program_info
        .iter()
        .filter(|d| d.tag == 0xC1)
        .collect();
    assert_eq!(c1.len(), 1);
    assert_eq!(c1[0].data[0] >> 6, 0b10, "digital_recording_control_data");
    assert_eq!(c1[0].data[0] & 0xF, 0b0100, "user_defined");
    // "source" without a ts-program stream is a configuration error
    let bad = Config::from_toml(
        &text
            .replace(
                "kind = \"ts-program\"",
                "kind = \"declared\"\n  pid = 0x0111\n  stream_type = 0x02",
            )
            .replace("pid_map = [[0x0140, 0x0111], [0x0141, 0x0112]]\n", "")
            .replace("eit_from_source = true\n", ""),
    );
    let e = match bad {
        Ok(bad) => bad.validate().unwrap_err().to_string(),
        Err(e) => e.to_string(),
    };
    assert!(e.contains("recording_control = \"source\""), "{e}");
}
